-- =====================================================================
-- «استمارة دعم وتطوير الهيئة التعليمية» وفق «نموذج تقييم أداء المعلم» المعتمد — النسخة الثانية من الدليل الإرشادي لإدارة الأداء الوظيفي.
--
-- • 11 عنصرًا بأوزانها المعتمدة (المجموع 100٪)، ولكل عنصر تفسيره وسلّم تقدير
--   من خمسة مستويات موصوفة، ومجالات التطوير يكتبها الزائر.
-- • جدول واحد بالعناصر من 1 إلى 11 بترتيب النموذج المعتمد وترقيمه.
-- • الجدولان القديمان (rb_class وrb_admin) يبقيان مخفيين في الإصدار (legacy)،
--   فتُطبع الاستمارات السابقة بشكلها كما صدرت.
--
-- يُنفَّذ مرة واحدة في Supabase ← SQL Editor، وتكرار التنفيذ آمن.
-- =====================================================================

with base as (
  select fields from public.form_templates where id = '767d1060-fb69-4888-8e64-32d787802bd5'
),
els as (
  select case when t.f->>'name' in ('rb_class', 'rb_admin') then t.f || '{"legacy": true}'::jsonb else t.f end as f, t.o
  from base, jsonb_array_elements(base.fields) with ordinality as t(f, o)
  where t.f->>'name' not in ('rb_perf', 'rb_perf_class', 'rb_perf_admin')
),
pos as (
  select coalesce((select o from els where f->>'name' = 'f4'), (select max(o) from els), 0) as p
),
added as (
  select '{"name": "rb_perf", "type": "rubric", "label": "عناصر تقييم أداء المعلم", "required": false, "style": "official", "items": [{"no": 1, "title": "أداء الواجبات الوظيفية", "weight": 10, "text": "يطبق الأنظمة وقواعد السلوك الوظيفية وأخلاقيات بيئة التعلم، كما يعزز الانتماء والولاء للوطن، والقيم الوطنية، ويحافظ على خصوصية المعلومات المهنية وحماية البيانات والمعلومات التي تتعلق بالعمل أو الأنشطة المهنية من الوصول غير المصرح به والامتثال للقوانين واللوائح وسياسات وإجراءات العمل التي تتوافق مع القوانين واللوائح المحلية والدولية.", "bullets": [], "levels": ["يُظهر الحد الأدنى للواجبات الوظيفية ويتأخر أو يتغيب عن العمل دون مبرر، ويُهمل ضوابط الأنظمة واللوائح.", "يُظهر التزامًا محدودًا، ويحتاج إلى توجيه مستمر، ويلتزم جزئيًا بالأنظمة والمواعيد مع وجود ثغرات في الأداء.", "يلتزم بمتطلبات الواجبات الوظيفية الأساسية، ويحافظ على المواعيد، ويؤدي المهام وفق ما هو متوقع.", "يلتزم التزامًا كاملًا بالأنظمة واللوائح، ويبادر بتحمّل المسؤوليات، ويدعم زملاءه في تحسين الأداء.\nيسهم بفاعلية في تعزيز قيم الانضباط والولاء بين الزملاء والطلاب.\nيعالج التحديات بشكل استباقي ويقترح حلولًا عملية قابلة للتطبيق لتحسين جودة الأداء المدرسي.", "يمثل قدوة في الالتزام والانضباط، ويبتكر ممارسات لتعزيز الولاء والانتماء تُعتمد كنموذج يحتذى به.\nيبتكر ممارسات أو آليات عمل جديدة تُعزز الالتزام والانضباط، ويتم تبنيها كنماذج يحتذى بها داخل المدرسة أو الإدارة التعليمية.\nيقود مبادرات نوعية أو مشروعات مستدامة تُحدث أثرًا ملموسًا في رفع كفاءة الأداء الجماعي وتحقيق قيمة مضافة للمجتمع التعليمي."]}, {"no": 2, "title": "التفاعل مع المجتمع المهني", "weight": 10, "text": "المشاركة الفعالة في مجتمعات وشبكات التعليم تسهم في تبادل المعرفة وتطوير المهارات المهنية وتعزيز أفضل الممارسات التعليمية. يشمل ذلك:", "bullets": ["التعلم المستمر من خلال التطوير المهني وورش العمل، والدورات والمؤتمرات.", "التعاون والتواصل لبناء شبكات مهنية، تبادل الأفكار ومواجهة التحديات التعليمية.", "الإسهام في التطوير: عبر الأبحاث، تطوير المناهج، ودعم السياسات التعليمية.", "الإرشاد والتوجيه بدعم المعلمين الجدد ومشاركة الخبرات.", "التفكير الذاتي: لتحسين الممارسات وبناء بيئة تعليمية تعزز التعلم المستمر والتطوير."], "levels": ["يُظهر مشاركة محدودة جدًا في الأنشطة المهنية، مع وعي أولي بأهمية المجتمع المهني.", "يشارك أحيانًا دون فعالية كبيرة، ويُظهر تفاعلًا محدودًا مع الزملاء.", "يشارك بانتظام، ويتعاون مع الزملاء عند الحاجة، ويُظهر مهارات مقبولة في تبادل المعرفة.", "يشارك بفاعلية في مجتمعات التعلم المهنية، وينقل خبراته للزملاء، ويُسهم في نشر ممارسات جيدة.\nيبادر بتنظيم أو تنسيق أنشطة مهنية (ورش، لقاءات، مجتمعات تعلم مهنية) تعزز من التعاون الجماعي.\nيسهم في معالجة التحديات التعليمية المشتركة عبر اقتراح حلول عملية وتبادل أفضل الممارسات.", "يقود مبادرات نوعية (ورش، بحوث، شبكات تعلم) يتم تبنيها على نطاق أوسع كممارسات مرجعية.\nيبتكر آليات أو أدوات جديدة لتعزيز تبادل الخبرات والمعرفة بين المعلمين، ويتم تبنيها كنماذج مرجعية.\nيمثل المدرسة/الإدارة في الفعاليات والمؤتمرات التعليمية كمصدر إلهام وخبرة متميزة، وينقل أثر مشاركته لتطوير المجتمع التعليمي."]}, {"no": 3, "title": "التفاعل مع أولياء الأمور", "weight": 10, "text": "المساهمة في دعم وتحقيق بيئة تعليمية فعالة لتحسين التحصيل الدراسي للطلبة وتعزيز تجربتهم لدعم التطور التعليمي والشخصي لهم، ويتضمن تفعيل قنوات اتصال فعالة مع أولياء الأمور لمناقشة تقدم الطلبة والتحديات التي قد تواجههم، وتشجيع أولياء الأمور على المشاركة في العملية التعليمية، مثل المساعدة في الواجبات المنزلية وتوفير بيئة داعمة، والتواصل المستمر مع أولياء الأمور باستخدام أساليب إيجابية لمناقشة التقدم العلمي والاجتماعي للمتعلمين وخطط التطوير المستقبلية للطلبة وإيجاد حلول مشتركة، والاستجابة والاستماع إلى مخاوف أولياء الأمور والعمل بشكل تعاوني لمعالجتها.", "bullets": [], "levels": ["يتواصل بشكل محدود جدًا مع أولياء الأمور عند الضرورة، ويُقدّم معلومات أساسية فقط.", "يتواصل بشكل متقطع، ويُقدّم معلومات غير كافية أو غير منتظمة.", "يتواصل عند الحاجة بانتظام مقبول، ويُقدّم معلومات واضحة عن أداء المتعلمين.", "يحافظ على تواصل مستمر ودوري مع أولياء الأمور، ويشركهم في متابعة تعلم أبنائهم، ويقترح حلولًا عملية.\nيشارك أولياء الأمور تحليلات نوعية وتوصيات عملية تساعدهم على متابعة تعلم أبنائهم بشكل أكثر فاعلية.\nيسهم في تعزيز العلاقة بين الأسرة والمدرسة عبر مبادرات جماعية مثل اللقاءات الدورية أو ورش التوعية.", "يقود مبادرات ابتكارية للتواصل مع أولياء الأمور (مثل المنصات الرقمية التفاعلية أو برامج الشراكة المجتمعية) يتم تبنيها كنموذج متميز في المدرسة أو الإدارة التعليمية.\nيبتكر أساليب وأدوات تسهم في رفع وعي أولياء الأمور بطرق تعليمية حديثة لدعم تعلم أبنائهم.\nيحقق شراكة استراتيجية مستدامة بين المدرسة والأسرة، تثمر عن أثر ملموس في تحصيل الطلبة وتطورهم الشخصي والاجتماعي."]}, {"no": 4, "title": "التنوع في استراتيجيات التدريس", "weight": 10, "text": "ويقصد بها قدرة المعلم على استخدام أساليب وطرائق تدريس مناسبة لتعزيز عملية التعلم. ويكون قادرًا على:", "bullets": ["استخدام استراتيجيات تدريس مناسبة للموقف التعليمي.", "استخدام استراتيجيات تدريس مناسبة لحاجات وميول المتعلمين.", "استخدام استراتيجيات تعمل على تنمية القدرة على التفكير والإبداع.", "استخدام استراتيجيات تنمي مهارات الحوار والمناقشة."], "levels": ["يعتمد فقط على طرق التدريس التقليدية والمباشرة مثل الشرح النظري دون إشراك المتعلمين.", "يستخدم استراتيجيات تدريس تقليدية، مع استخدام محدود لبعض الطرق الحديثة للأنشطة التعليمية التي لا تتناسب مع أهداف التدريس.", "يستخدم استراتيجيات تدريس مناسبة متنوعة وفعالة بشكل منتظم، وقد يواجه صعوبة في التطبيق الفعال.", "يوظف استراتيجيات تدريس متنوعة تراعي الفروق الفردية، ويشارك خبراته مع الزملاء لتحسين الممارسات.\nيطبق بفاعلية استراتيجيات تدريس متنوعة تتجاوز المألوف، مع دمج التقنيات التعليمية والأنشطة الإثرائية لزيادة تفاعل المتعلمين.\nيبادر بمشاركة زملائه أفضل الممارسات التدريسية، ويسهم في تطوير أنشطة جماعية تعزز التفكير الناقد والإبداع.\nيعالج التحديات الصفية باستخدام أساليب مبتكرة تراعي الفروق الفردية وتدعم تحسين الأداء الجماعي للمتعلمين.", "يبتكر استراتيجيات تدريس جديدة مبنية على الأدلة والبحوث التربوية، ويتم اعتمادها كنموذج متميز داخل المدرسة.\nيبتكر نماذج واستراتيجيات تدريس جديدة تُعتمد كأفضل ممارسات داخل المدرسة أو الإدارة التعليمية.\nيقود مبادرات نوعية أو برامج تدريبية لزملائه في مجال التنويع التدريسي، مما يترك أثرًا مستدامًا على بيئة التعلم.\nيوظف استراتيجيات إبداعية متقدمة وينجح في إحداث نقلة نوعية في تجربة تعلم الطلاب."]}, {"no": 5, "title": "تحسين نتائج المتعلمين", "weight": 10, "text": "عملية تحسين التحصيل الدراسي تهدف إلى معالجة نقاط الضعف وتطوير نقاط القوة في أداء المتعلمين الأكاديمي وتنمية مهاراتهم. تشمل:", "bullets": ["تحديد أهداف ومعايير واضحة ليعرف المتعلمون ما يُتوقع منهم تحقيقه.", "تقديم إفادة سريعة ومحددة فور ملاحظة الأداء، مع التركيز على الإيجابيات وتقديم اقتراحات بناءة للتحسين.", "تكييف الإفادة وفق الاحتياجات الفردية لضمان التفاعل الفعّال وتشجيع المتعلمين على طرح الأسئلة وتطبيق الاقتراحات.", "تعزيز الثقة وتشجيع التطور من خلال تقديم ملاحظات تشجيعية وفرص لتحسين الأداء.", "استخدام التكنولوجيا لتقديم الإفادة بطرق مبتكرة مثل البريد الإلكتروني ومنصات التعلم."], "levels": ["نادرًا ما يوفر أي دعم للمتعلمين الذين يواجهون صعوبات في الأداء.", "يوفر بعض الدعم للمتعلمين، لكنه غير كافٍ لتحسين أدائهم بشكل ملموس.", "يُقدم دعمًا إضافيًا للمتعلمين ذوي الأداء الضعيف، ويضع أهدافًا تساهم في تحسين مستوى المتعلمين.", "يشخّص مواطن الضعف ويطبق خططًا علاجية مناسبة، ويُظهر تحسنًا ملحوظًا في نتائج الطلاب.\nيطبق خططًا علاجية جماعية وفردية لمعالجة الفاقد التعليمي، ويتابع التقدم بانتظام، ويقترح حلولًا لتحسين الأداء المدرسي.\nيطبق استراتيجيات علاجية متقدمة تتجاوز الخطط الفردية لتشمل مبادرات صفية وجماعية ترفع من مستوى جميع المتعلمين.\nيتابع التحصيل بشكل منتظم باستخدام أدوات تقييم متنوعة، ويشرك المتعلمين في وضع أهداف تعلم شخصية.\nيشارك خبراته مع الزملاء عبر اقتراح حلول عملية لمعالجة فجوات التعلم المشتركة وتحسين الأداء المدرسي ككل.", "يقود مبادرات نوعية لرفع نتائج التعلم بشكل شامل، ويُبتكر حلولًا تعليمية تُسهم في تحقيق قفزات نوعية في التحصيل.\nيطور برامج علاجية مبتكرة للفاقد التعليمي، ويتم تبنيها على مستوى المدرسة أو الإدارة التعليمية، ويحقق أثرًا مستدامًا في رفع نتائج التعلم.\nيبتكر برامج أو أدوات تعليمية رقمية أو منهجية معتمدة على البيانات تعزز تحسين نتائج التعلم بشكل مستدام.\nيقود مبادرات نوعية (مثل منصات متابعة التحصيل أو مجتمعات تعلم للطلاب) ويتم تبنيها كنموذج يحتذى به في المدرسة أو الإدارة التعليمية.\nيحقق نقلة نوعية ملموسة في نتائج التعلم، ليس فقط على مستوى طلابه، بل عبر تأثيره في تحسين أداء المدرسة بشكل عام."]}, {"no": 6, "title": "إعداد وتنفيذ خطة التعلم", "weight": 10, "text": "ويقصد بها تمكن المعلم من إعداد خطة منظمة تساعد على تحديد الأهداف التعليمية وتنفيذها بوضوح مما يحسن ويجود الأداء التدريسي. ويكون قادرًا على:", "bullets": ["إعداد خطة التعلم وفق السياسات المنظمة لذلك، وبما يواءم مع تشخيص واقع المتعلمين.", "تحقيق الأهداف التعليمية وعناصر المواد المسندة إليه.", "التخطيط للأنشطة الصفية والأنشطة غير الصفية من قبل المعلم الخبير (إن وجد).", "مشاركة المعلم الممارس والمعلم المتقدم في الإعداد والتنفيذ للأنشطة الصفية والأنشطة غير الصفية.", "تفهم الخصائص النفسية للمرحلة العمرية التي يقوم بتدريسها."], "levels": ["نادرًا ما يقوم بإعداد خطة التعلم ويعتمد بشكل كامل على التدريس المباشر دون إعداد مسبق.", "يقوم بإعداد خطة تعلم تتضمن أهداف تعليمية غير واضحة، ويعتمد على المواد الجاهزة دون تخصيص أو تطوير المحتوى ليتناسب مع المتعلمين. ويفتقر إلى التنويع في أساليب التدريس.", "يقوم بإعداد خطة تعلم تتضمن أهدافًا تعليمية واضحة ومحددة تراعي الفروق الفردية بين المتعلمين وتغطي المحتوى التعليمي.", "يضع خطط تعلم متكاملة تراعي الفروق الفردية، ويشارك زملاءه في تطوير الخطط وتحسينها وفق نتائج الأداء.\nيضع خطط تعلم متكاملة تراعي الفروق الفردية بعمق وتدمج أنشطة إثرائية تعزز التعاون الجماعي ومهارات التفكير العليا.\nيبادر بمراجعة الخطط وتطويرها بشكل مستمر بناءً على تحليل أداء الطلاب ونتائج التقييم.\nيشارك زملاءه خططه كمرجع عملي لتحسين جودة التخطيط التدريسي على مستوى المدرسة.", "يبتكر خطط تعلم مرنة وذكية تراعي التغيرات وتُعتمد كنموذج يُحتذى به في التخطيط والتنفيذ.\nيبتكر نماذج تخطيط متقدمة (دمج التقنية/التعليم المخصص)، ويقود مبادرات لتطوير السياسات والبرامج التعليمية على مستوى المدرسة.\nيبتكر نماذج تخطيط تعليمية متقدمة (مثل دمج التقنية أو التعليم المخصص) يتم تبنيها كنموذج رائد داخل المدرسة أو الإدارة التعليمية.\nيقود مبادرات جماعية لتطوير الخطط الدراسية، ويُسهم في صياغة أدلة أو أدوات تخطيط معتمدة تدعم المعلمين الآخرين.\nيحدث نقلة نوعية في جودة التعلم عبر خطط تعليمية مستدامة تعزز مخرجات الطلاب وتتكامل مع الأهداف الاستراتيجية للمؤسسة التعليمية."]}, {"no": 7, "title": "توظيف تقنيات ووسائل التعلم المناسبة", "weight": 10, "text": "ويقصد بها قدرة المعلم على استخدام الوسائل التعليمية والأدوات المتنوعة المناسبة للموقف التعليمي لتحسين العملية التعليمية. ويكون قادرًا على:", "bullets": ["تنويع تقنيات ووسائل التعلم المناسبة بغرض تحقيق الأهداف التعليمية بفاعلية.", "مراعاة الفروق الفردية بين المتعلمين لتيسير نقل الخبرات التعليمية بسهولة ووضوح.", "استخدام التقنيات والوسائل التعليمية المناسبة لحاجات وأنماط المتعلمين.", "إكساب الطلبة المعرفة وتنمية قدراتهم على التأمل والملاحظة والتفكير العلمي للوصول إلى حل المشكلات."], "levels": ["نادرًا ما يستخدم التقنيات والوسائل التعليمية المناسبة.", "يستخدم التقنيات والوسائل التعليمية بشكل محدود ولا تتناسب مع المحتوى التعليمي.", "يستخدم أغلب التقنيات والوسائل التعليمية المناسبة ويوظفها بشكل منتظم وتتناسب مع المحتوى التعليمي.", "يوظف التقنيات بفاعلية عالية لدعم التفاعل الصفي، ويُبادر إلى تدريب زملائه على الاستفادة منها.\nيوظف تقنيات ووسائل تعلم متنوعة بفاعلية عالية، مع تكييفها لتلبية الاحتياجات الفردية والجماعية للمتعلمين.\nيشارك في تدريب زملائه على استخدام الوسائل التقنية داخل الصفوف، مما يعزز الأداء الجماعي.\nيبادر إلى ابتكار أنشطة صفية تفاعلية باستخدام الأدوات التقنية المتاحة، بما يحفز المشاركة ويطور مهارات التفكير لدى المتعلمين.", "يبتكر أدوات تعليمية رقمية جديدة، ويقود مبادرات تقنية (منصات تعلم، مختبرات رقمية) تُحدث نقلة نوعية في بيئة التعلم.\nيبتكر طرقًا جديدة لدمج التقنية بالتعليم، مثل تصميم أدوات رقمية أو تفاعلية تُسهم في رفع مستوى التحصيل وتنمية مهارات القرن 21.\nيقود مبادرات أو مشروعات نوعية في المدرسة (مثل الصفوف الافتراضية أو المختبرات الرقمية) ويتم اعتمادها كنموذج متميز.\nيحقق أثرًا نوعيًا مستدامًا من خلال تطوير بيئة تعليمية رقمية متكاملة تسهّل التعلّم الشخصي، وتُسهم في تحسين جودة التعليم على نطاق أوسع."]}, {"no": 8, "title": "تهيئة البيئة التعليمية", "weight": 5, "text": "ويقصد بها قدرة المعلم على ممارسة عمليات تتضمن المدخلات والعمليات والإجراءات اللازمة والتي توفر للمتعلمين على اختلاف قدراتهم وميولهم واهتماماتهم واحتياجاتهم التعليمية فرصًا متكافئة لفهم واستيعاب المفاهيم واستخدامها في مواقف الحياة اليومية. ويكون قادرًا على:", "bullets": ["توفير بيئة تعليمية آمنة تشجع على التعلم وتدعم النمو الشخصي والأكاديمي.", "توفير بيئة تعليمية تحقق الأمان النفسي وتتسم بالاحترام المتبادل.", "توفير بيئة تعليمية تمكن المتعلمين من التعبير عن أنفسهم ومشاركة أفكارهم مع أقرانهم.", "إثارة دافعية المتعلمين من خلال التنويع في أساليب التعلم."], "levels": ["نادرًا ما يخلق بيئة تعليمية محفزة أو داعمة للتعلم النشط.", "يبني بيئة تعليمية تعزز فهم الطالب بشكل جزئي للمعرفة.", "يبني بيئة تعليمية تعزز فهم الطالب للمعرفة وتراعي الفروق الفردية بين المتعلمين.", "يبني بيئة صفية آمنة ومحفزة، ويشجع على التعاون والعمل الجماعي، ويُرسخ القيم الإيجابية والانضباط الذاتي.\nيبني بيئة تعليمية تفاعلية تراعي التنوع الثقافي والمعرفي للمتعلمين، وتشجع على التعاون والعمل الجماعي.\nيبادر بتطبيق استراتيجيات الإدارة الصفية الإيجابية التي تقلل من السلوكيات السلبية وتعزز الانضباط الذاتي.\nيشارك بفاعلية في تصميم أنشطة صفية ولاصفية تعزز الدافعية، وتدعم نمو المتعلمين الأكاديمي والشخصي.", "يبتكر بيئات تعليمية إبداعية ويقود مبادرات تعزز الثقافة التعليمية الإيجابية داخل المدرسة والمجتمع.\nيبتكر بيئات تعلم إبداعية وملهمة يتم تبنيها كنموذج يحتذى به.\nيحقق أثرًا نوعيًا مستدامًا في تحفيز المتعلمين عبر أساليب حديثة.\nيقود مبادرات أو برامج نوعية ترفع من جودة البيئة التعليمية على مستوى المدرسة أو الإدارة، وتترك بصمة مميزة في تعزيز الثقافة التعليمية الإيجابية."]}, {"no": 9, "title": "الإدارة الصفية", "weight": 5, "text": "ويقصد بها جميع الخطوات والإجراءات اللازمة لتحقيق بيئة صفية آمنة وجاذبة وملائمة لعمليتي التعلم والتعليم تأخذ بعين الاعتبار الأبعاد النفسية والاجتماعية والعقلية والجسمية للمتعلم، مما يساعد على تحقيق الأهداف التعليمية المنشودة ويكون قادرًا على:", "bullets": ["مراعاة الفروق الفردية بين المتعلمين.", "توجيه المتعلمين لتطبيق القوانين والتعليمات الصفية.", "تعزيز الانضباط عند المتعلمين وتنظيم عملية التفاعل والتواصل بينهم.", "تنظيم الطلاب بما يناسب الموقف المدرسي."], "levels": ["نادرًا ما يدير الصف بفاعلية.", "يدير الصف دون مراعاة القوانين والتعليمات الصفية.", "يدير الصف بفاعلية ويظهر قدرة على توجيه المتعلمين لتطبيق القوانين والتعليمات الصفية.", "يدير الصف بفاعلية، ويُشرك المتعلمين في وضع القوانين الصفية لتعزيز التزامهم وانضباطهم الذاتي، ويتعاون مع زملائه لتحسين الممارسات الصفية.\nيدير الصف بفاعلية عالية، مع توظيف استراتيجيات مبتكرة للإدارة الصفية تعزز المشاركة الجماعية وتحد من السلوكيات السلبية.\nيبادر إلى بناء بيئة صفية تشاركية تُشرك المتعلمين في وضع قواعد الصف، مما يعزز من التزامهم وانضباطهم الذاتي.\nيتعاون مع الزملاء لتطوير خطط جماعية للإدارة الصفية تدعم تحسين البيئة التعليمية على مستوى المدرسة.", "يبتكر نماذج إدارة صفية متقدمة (دمج تقنيات، أساليب تشاركية)، ويقود مبادرات تعزز الثقافة الصفية الإيجابية، ويتم اعتمادها كنموذج على مستوى المدرسة.\nالقدرة على التعامل مع الطلبة وفق احتياجاتهم.\nيبتكر نماذج جديدة للإدارة الصفية (مثل الدمج بين الأساليب الرقمية والتقليدية أو التعلم التعاوني) يتم تبنيها كنموذج مرجعي في المدرسة أو الإدارة التعليمية.\nيقود مبادرات نوعية لتعزيز الثقافة الصفية الإيجابية داخل المدرسة، وينجح في خلق بيئة تعليمية مستدامة داعمة للانضباط والتعلم النشط.\nيحقق أثرًا نوعيًا ملموسًا من خلال تطوير قدرات الطلاب على الانضباط الذاتي، وإدارة تعلمهم بوعي ومسؤولية."]}, {"no": 10, "title": "تحليل نتائج المتعلمين وتشخيص مستوياتهم", "weight": 10, "text": "تحليل البيانات لتطوير التعلم عملية تستخلص الحقائق والاستنتاجات من البيانات لتقييم أداء المتعلمين بوضوح وتقديم تغذية راجعة بناءة. تشمل:", "bullets": ["تنويع مصادر التقييم لضمان شمولية النتائج وتقليل التحيز.", "تطوير أهداف تعليمية قصيرة وطويلة المدى تراعي الفروق الفردية وبيئة التعلم.", "تفسير البيانات: لاتخاذ قرارات مستنيرة بشأن فعالية التدريس والمناهج.", "قياس التطبيق العملي للمعرفة عبر مواقف ومشاريع حقيقية.", "تحليل الأداء العام لتحديد نقاط القوة والضعف، مع إشراك المتعلمين في فهم نتائجهم وتقديم ملاحظات تدعم التطور المستمر."], "levels": ["نادرًا ما يقوم بتحليل نتائج المتعلمين بشكل منهجي.", "يُجري تحليلًا محدودًا للنتائج، ولكن دون الاعتماد على أدوات أو أساليب دقيقة.", "يُجري تحليلًا أساسيًا لنتائج المتعلمين باستخدام بعض الأدوات أو الأساليب المتاحة.", "يجمع بيانات متنوعة، يحللها بانتظام، ويُصدر تقارير تشخيصية عملية، ويشاركها مع زملائه لتطوير الخطط التعليمية.\nيجمع ويحلل بيانات المتعلمين من مصادر متعددة (اختبارات، أنشطة صفية، ملاحظات)، ويستخدمها بفاعلية لتشخيص الاحتياجات الفردية والجماعية.\nيبادر بتقديم تقارير تحليلية عملية توضح الفجوات التعليمية وتقترح معالجات قابلة للتنفيذ.\nيشارك نتائجه مع الزملاء بشكل دوري، مما يسهم في تحسين الأداء الجماعي للمدرسة.", "يبتكر أدوات تحليل وتشخيص متقدمة (لوحات متابعة رقمية، أنظمة ذكية) ويقود مبادرات لتحويل البيانات إلى رؤى استراتيجية تُسهم في رفع مستوى المدرسة.\nيطور أدوات تحليل وتشخيص مبتكرة (مثل لوحات متابعة رقمية أو نماذج تحليل بياني) يتم تبنيها كنموذج متميز.\nيقود مبادرات نوعية لاستخدام البيانات في تحسين القرارات التعليمية، مثل تطوير خطط تعلم فردية أو جماعية مستندة إلى التحليل المتقدم.\nيحدث أثرًا نوعيًا مستدامًا عبر تحويل البيانات إلى رؤى استراتيجية تُسهم في رفع كفاءة العملية التعليمية على مستوى المدرسة أو الإدارة التعليمية."]}, {"no": 11, "title": "تنوع أساليب التقويم", "weight": 10, "text": "ويقصد بها استخدام مجموعة متنوعة من الطرق وتتوافق مع أهداف التعلم مع التأكد من أن الأدوات والنماذج والتي تتسم بأنها واضحة ومحددة وصادقة وموثوقة وتقيّم ما هو مقصود بها، لتقييم التقدم والإنجازات الأكاديمية للمتعلمين خلال فترة زمنية محددة ويكون قادرًا على:", "bullets": ["معرفة وفهم أساليب وأدوات التقويم المتنوعة.", "معرفة وفهم خصائص نمو المتعلمين وأساليب تعلمهم.", "استخدام مصادر متنوعة للتقييم مثل الملاحظة الصفية، الاستبانات، التقارير الذاتية، تحليل نتائج المتعلمين.", "توظيف أساليب تقويم متنوعة على أن يكون من ضمنها الاختبارات (شفهية، تحريرية) والمهمات الأدائية التي تتناسب مع طبيعة الأهداف ومخرجات التعلم.", "مراعاة الفروق الفردية بين المتعلمين أثناء التقويم وتقديم التغذية الراجعة لرفع مستوى التحصيل الدراسي.", "الاستفادة من نتائج تنوع أساليب وأدوات التقويم بتوظيفها في تحسين مستوى الأداء بصفة مستمرة.", "استخدام التقويم القبلي (التشخيصي) للوقوف على مدى استعداد المتعلمين وتشخيص امتلاكهم لمهارات وخبرات أساسية سابقة.", "تطبيق التقويم التكويني أثناء عملية التعلم لبناء وتطوير المهارات والكفايات لدى المتعلمين وإصدار أحكام عن مستوياتهم وفق معايير كمية ونوعية يقاس من خلالها التعلم.", "تطبيق التقويم الختامي لمعرفة مدى تحقق أهداف العملية التعليمية وقياس تقدم التعلم وإصدار أحكام عن مستويات الطلبة."], "levels": ["نادرًا ما يستخدم أساليب وأدوات تقييم مناسبة.", "يعتمد فقط على نوع واحد من أساليب التقييم، لكنه قد لا يكون شاملًا بشكل كافٍ.", "يستخدم أساليب وأدوات تقييم مناسبة تقوم على أسس علمية، ويُوظف مجموعة من أساليب التقييم متوافقة مع طبيعة الأهداف ومخرجات التعلم.", "يستخدم أدوات تقويم متنوعة (كتابية، عملية، إلكترونية)، ويُبادر إلى اقتراح تحسينات في أساليب التدريس بناءً على نتائجها.\nيوظف أساليب تقويم متنوعة ترتبط بالأهداف التعليمية، ويحرص على استخدام أدوات تحليلية وتقنية لتتبع تقدم المتعلمين بانتظام.\nيبادر بمشاركة نتائج التحليل مع الزملاء ويقترح خططًا عملية لتحسين طرق التدريس بناءً على بيانات التقويم.\nيدمج بين أساليب تقليدية وحديثة بشكل متوازن يثري عملية التعلم ويدعم الأداء الجماعي.", "يطور أدوات تقويم مبتكرة، ويقود مبادرات مدرسية أو بحثية توظف نتائج التقويم كأداة استراتيجية لتحسين جودة التعليم على نطاق واسع.\nيبتكر أو يطور أدوات تقويم رقمية أو منهجية جديدة (مثل لوحات متابعة ذكية أو نماذج تقييم مبتكرة) يتم اعتمادها كنموذج متميز.\nيقود مبادرات نوعية في المدرسة/الإدارة لاستخدام نتائج التقويم كأداة استراتيجية لتحسين جودة التعليم.\nيحقق أثرًا نوعيًا مستدامًا عبر تحويل نتائج التقويم إلى رؤى قابلة للتنفيذ على مستوى المدرسة، مما يرفع مستوى التحصيل العام للمتعلمين."]}]}'::jsonb as f, (select p from pos) * 10 + 3 as k
),
allx as (
  select f, o * 10 as k from els
  union all
  select f, k from added
)
update public.form_templates
set fields = (select jsonb_agg(f order by k) from allx),
    updated_at = now()
where id = '767d1060-fb69-4888-8e64-32d787802bd5';

-- للتحقق: جدول العناصر الجديد بعد «تاريخ الزيارة»، والجدولان القديمان legacy
select f->>'name' as name, f->>'label' as label, f->>'type' as type, coalesce(f->>'legacy', '') as legacy,
       jsonb_array_length(coalesce(f->'items', '[]'::jsonb)) as items
from public.form_templates, jsonb_array_elements(fields) f
where id = '767d1060-fb69-4888-8e64-32d787802bd5';
